val Bg=Color(0xFF080A0D);val Surface=Color(0xFF111419);val Elevated=Color(0xFF181C22);val Border=Color(0xFF252A32);val Ink=Color(0xFFF5F7F8);val Muted=Color(0xFF969DA8);val Mint=Color(0xFF8AFFB5);val Warn=Color(0xFFFFCC66);val Err=Color(0xFFFF7070)
data class Session(val start:Long,val end:Long,val experimentDay:Int,val planned:Int,val actual:Int,val urges:Int,val focus:Int,val goal:String,val output:String,val interrupted:Boolean)
class Store(c:Context){val p=c.getSharedPreferences("ioff",0);fun day()=p.getInt("day",1).coerceIn(1,7);fun k(x:String,d:Int=day())=MetricKeys.experiment(d,x);fun metric(x:String,d:Int=day())=p.getInt(k(x,d),0);fun add(x:String,n:Int,d:Int=day())=p.edit().putInt(k(x,d),metric(x,d)+n).apply();fun total(x:String)=(1..7).sumOf{metric(x,it)};fun sessions():List<Session>{val raw=p.getString("sessions_json","[]")?:"[]";return try{val a=JSONArray(raw);val r=mutableListOf<Session>();for(i in 0 until a.length()){val o=a.getJSONObject(i);r.add(Session(o.optLong("start"),o.optLong("end"),o.optInt("experimentDay",1),o.optInt("planned"),o.optInt("actual"),o.optInt("urges"),o.optInt("focus"),o.optString("goal"),o.optString("output"),o.optBoolean("interrupted")))};r}catch(_:Exception){emptyList()}};fun save(s:Session){val a=try{JSONArray(p.getString("sessions_json","[]")?:"[]")}catch(_:Exception){JSONArray()};a.put(JSONObject().put("start",s.start).put("end",s.end).put("experimentDay",s.experimentDay).put("planned",s.planned).put("actual",s.actual).put("urges",s.urges).put("focus",s.focus).put("goal",s.goal).put("output",s.output).put("interrupted",s.interrupted));p.edit().putString("sessions_json",a.toString()).apply();add("mins",s.actual,s.experimentDay);add("urges",s.urges,s.experimentDay);add("sessions",1,s.experimentDay);add("focusSum",s.focus,s.experimentDay)};fun ideas()=IdeaCodec.parse(p.getString("ideas","")?:"");fun park(t:String){p.edit().putString("ideas",IdeaCodec.prepend(p.getString("ideas","")?:"",System.currentTimeMillis(),t)).apply()};fun updateIdea(x:ParkedIdea,t:String){p.edit().putString("ideas",IdeaCodec.update(p.getString("ideas","")?:"",x.timestamp,t)).apply()};fun deleteIdea(x:ParkedIdea){p.edit().putString("ideas",IdeaCodec.delete(p.getString("ideas","")?:"",x.timestamp)).apply()}}
class MainActivity:ComponentActivity(){lateinit var store:Store;override fun onCreate(b:Bundle?){super.onCreate(b);store=Store(this);recover();setContent{Theme{Root(this,store)}}};fun startFocus(goal:String,min:Int){val g=FocusRules.normalizedGoal(goal);if(!FocusRules.canStart(g))return;val m=FocusRules.durationMinutes(min);val now=System.currentTimeMillis();val nm=getSystemService(NotificationManager::class.java);val e=store.p.edit().putBoolean("focus_active",true).putLong("focus_start",now).putLong("focus_end",now+m*60000L).putInt("focus_day",store.day()).putInt("focus_planned",m).putInt("focus_urges",0).putString("goal",g);if(nm?.isNotificationPolicyAccessGranted==true){e.putInt("prev_filter",nm.currentInterruptionFilter).putBoolean("dnd_changed",true);nm.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_PRIORITY)};e.commit()};fun restoreDnd(){val nm=getSystemService(NotificationManager::class.java);if(store.p.getBoolean("dnd_changed",false)&&nm?.isNotificationPolicyAccessGranted==true){runCatching{nm.setInterruptionFilter(store.p.getInt("prev_filter",NotificationManager.INTERRUPTION_FILTER_ALL))};store.p.edit().putBoolean("dnd_changed",false).apply()}};fun recover(){if(store.p.getBoolean("focus_active",false)&&store.p.getLong("focus_end",0)<=System.currentTimeMillis()){restoreDnd();store.p.edit().putBoolean("focus_expired",true).apply()}};fun finish(interrupted:Boolean):Session{val p=store.p;val start=p.getLong("focus_start",System.currentTimeMillis());val planned=p.getInt("focus_planned",60);val actual=((System.currentTimeMillis()-start)/60000).toInt().coerceIn(0,planned);restoreDnd();return Session(start,System.currentTimeMillis(),p.getInt("focus_day",store.day()),planned,if(!interrupted&&actual<planned)planned else actual,p.getInt("focus_urges",0),0,p.getString("goal","")?:"","",interrupted)};fun complete(x:Session,score:Int,out:String){store.save(x.copy(focus=score,output=out.trim()));store.p.edit().putBoolean("focus_active",false).putBoolean("focus_expired",false).apply()};fun dnd()=getSystemService(NotificationManager::class.java)?.isNotificationPolicyAccessGranted==true}
@Composable fun Theme(c: @Composable () -> Unit){val base=Typography();MaterialTheme(colorScheme=darkColorScheme(primary=Mint,background=Bg,surface=Surface,surfaceVariant=Elevated,onBackground=Ink,onSurface=Ink,error=Err),typography=Typography(headlineLarge=base.headlineLarge.copy(fontWeight=FontWeight.Bold),titleLarge=base.titleLarge.copy(fontWeight=FontWeight.Bold)),content=c)}
@Composable fun Root(a:MainActivity,s:Store){var tab by remember{mutableIntStateOf(0)};var rev by remember{mutableIntStateOf(0)};var ideas by remember{mutableStateOf(false)};var shutdown by remember{mutableStateOf(false)};rev;val active=s.p.getBoolean("focus_active",false);if(ideas){Ideas(s){ideas=false;rev++};return};if(shutdown){Shutdown(s){shutdown=false;rev++};return};Scaffold(containerColor=Bg,bottomBar={if(!active)NavigationBar(containerColor=Surface,tonalElevation=0.dp){val names=listOf("Today","Focus","Progress","More");val icons=listOf(Icons.Outlined.Home,Icons.Outlined.Timer,Icons.Outlined.Insights,Icons.Outlined.Tune);names.indices.forEach{i->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Icon(icons[i],null)},label={Text(names[i])},colors=NavigationBarItemDefaults.colors(selectedIconColor=Bg,selectedTextColor=Mint,indicatorColor=Mint,unselectedIconColor=Muted,unselectedTextColor=Muted))}}}){pad->Box(Modifier.padding(pad)){if(active)Active(a,s){rev++}else when(tab){0->V05Today(s,{tab=1},{ideas=true});1->FocusSetup(a,s){rev++};2->AttentionProgress(s);else->More(a,s,{shutdown=true},{ideas=true})}}}}
@Composable fun Page(title:String,c: @Composable ColumnScope.() -> Unit){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(horizontal=20.dp,vertical=18.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("iOff",fontSize=27.sp,fontWeight=FontWeight.Black,color=Mint,letterSpacing=(-1).sp);Spacer(Modifier.weight(1f));Text(title.uppercase(),color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold,letterSpacing=1.2.sp)};Spacer(Modifier.height(24.dp));c();Spacer(Modifier.height(18.dp))}}
@Composable fun CardX(c: @Composable ColumnScope.() -> Unit){Card(modifier=Modifier.fillMaxWidth().padding(vertical=6.dp),shape=RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(containerColor=Surface),border=BorderStroke(1.dp,Border)){Column(Modifier.padding(18.dp),content=c)}}
