@Composable fun FocusSetup(a:MainActivity,s:Store,done:()->Unit){var goal by remember{mutableStateOf(s.p.getString("focus_prefill","")?:"")};var min by remember{mutableIntStateOf(60)};Page("Focus"){Text("Finish one thing.",fontSize=35.sp,fontWeight=FontWeight.Bold,letterSpacing=(-1).sp);Text("Everything else can wait.",color=Muted,fontSize=15.sp,modifier=Modifier.padding(top=5.dp,bottom=18.dp));CardX{Text("WHAT ARE YOU FINISHING?",color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold);OutlinedTextField(goal,{goal=it},Modifier.fillMaxWidth().padding(top=8.dp),placeholder={Text("A concrete outcome")},shape=RoundedCornerShape(18.dp));Text("DURATION",color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=18.dp,bottom=6.dp));Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf(30,60,90,120).forEach{FilterChip(min==it,{min=it},{Text("${it} min")})}}};CardX{Row(verticalAlignment=Alignment.CenterVertically){Surface(color=if(a.dnd())Mint.copy(alpha=.12f) else Warn.copy(alpha=.12f),shape=RoundedCornerShape(14.dp)){Icon(Icons.Outlined.Shield,null,tint=if(a.dnd())Mint else Warn,modifier=Modifier.padding(10.dp))};Column(Modifier.padding(start=12.dp)){Text("Focus Protection",fontWeight=FontWeight.Bold);Text(if(a.dnd())"Do Not Disturb is ready" else "Enable Do Not Disturb access",color=if(a.dnd())Mint else Warn,fontSize=12.sp)}}};Primary("Begin Focus  →",goal.isNotBlank()){a.startFocus(goal,min);done()}}}
@Composable fun Active(a:MainActivity,s:Store,done:()->Unit){var now by remember{mutableLongStateOf(System.currentTimeMillis())};var pending by remember{mutableStateOf<Session?>(null)};var park by remember{mutableStateOf(false)};LaunchedEffect(Unit){while(pending==null){now=System.currentTimeMillis();if(now>=s.p.getLong("focus_end",0)){pending=a.finish(false);break};delay(1000)}};pending?.let{Complete(a,it,done);return};val rem=(s.p.getLong("focus_end",0)-now).coerceAtLeast(0);Box(Modifier.fillMaxSize().background(Bg).padding(24.dp)){Column(Modifier.align(Alignment.Center),horizontalAlignment=Alignment.CenterHorizontally){Surface(color=Mint.copy(alpha=.10f),shape=RoundedCornerShape(50.dp)){Text("●  FOCUS ACTIVE",color=Mint,fontSize=11.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(horizontal=15.dp,vertical=8.dp))};Spacer(Modifier.height(24.dp));Text(String.format("%02d:%02d",rem/60000,(rem/1000)%60),fontSize=68.sp,fontWeight=FontWeight.Black,letterSpacing=(-3).sp);Text(s.p.getString("goal","")?:"",fontSize=19.sp,fontWeight=FontWeight.SemiBold,modifier=Modifier.padding(top=8.dp),color=Ink);Text("One task. One screen.",color=Muted,fontSize=13.sp,modifier=Modifier.padding(top=5.dp,bottom=28.dp));Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){OutlinedButton({s.p.edit().putInt("focus_urges",s.p.getInt("focus_urges",0)+1).apply()},shape=RoundedCornerShape(16.dp)){Text("⚡ Urge")};OutlinedButton({park=true},shape=RoundedCornerShape(16.dp)){Text("＋ Park idea")}}};TextButton({pending=a.finish(true)},Modifier.align(Alignment.BottomCenter)){Text("End session",color=Muted)}};if(park){var t by remember{mutableStateOf("")};AlertDialog(onDismissRequest={park=false},confirmButton={Button(onClick={s.park(t);park=false},enabled=t.isNotBlank()){Text("Park")}},dismissButton={TextButton({park=false}){Text("Cancel")}},title={Text("Park the idea")},text={OutlinedTextField(t,{t=it},placeholder={Text("Capture it. Don't switch projects.")},shape=RoundedCornerShape(16.dp))})}}
@Composable fun Complete(a:MainActivity,x:Session,done:()->Unit){var out by remember{mutableStateOf("")};var score by remember{mutableIntStateOf(8)};Page("Complete"){Text("Protected.",color=Mint,fontSize=12.sp,fontWeight=FontWeight.Bold);Text("${x.actual} minutes of real work.",fontSize=34.sp,fontWeight=FontWeight.Bold,letterSpacing=(-1).sp,modifier=Modifier.padding(bottom=18.dp));CardX{OutlinedTextField(out,{out=it},Modifier.fillMaxWidth(),label={Text("What exists now?")},shape=RoundedCornerShape(18.dp));Text("FOCUS QUALITY",color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=18.dp));Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(5.dp)){(1..10).forEach{FilterChip(score==it,{score=it},{Text("$it")})}}};Primary("Save session  ✓"){a.complete(x,score,out);done()}}}
@Composable fun Ideas(s:Store,back:()->Unit){var q by remember{mutableStateOf("")};var edit by remember{mutableStateOf<ParkedIdea?>(null)};var rev by remember{mutableIntStateOf(0)};var add by remember{mutableStateOf("")};rev;Page("Ideas"){Row(verticalAlignment=Alignment.CenterVertically){TextButton(back){Text("← Back",color=Muted)};Spacer(Modifier.weight(1f));Button({if(add.isNotBlank()){s.park(add);add="";rev++}},enabled=add.isNotBlank(),shape=RoundedCornerShape(16.dp)){Text("+ Park idea")}};Text("Idea Parking",fontSize=35.sp,fontWeight=FontWeight.Bold,letterSpacing=(-1).sp);Text("Capture it. Don't switch projects.",color=Muted,modifier=Modifier.padding(top=4.dp,bottom=16.dp));OutlinedTextField(add,{add=it},Modifier.fillMaxWidth(),placeholder={Text("What's pulling at your attention?")},shape=RoundedCornerShape(18.dp));OutlinedTextField(q,{q=it},Modifier.fillMaxWidth().padding(top=9.dp),leadingIcon={Icon(Icons.Outlined.Search,null)},placeholder={Text("Search parked ideas")},shape=RoundedCornerShape(18.dp));val shown=s.ideas().filter{q.isBlank()||it.text.contains(q,true)};Text("${shown.size} IDEAS",color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=18.dp));shown.forEach{x->CardX{Row{Column(Modifier.weight(1f)){Text(x.text,fontSize=17.sp,fontWeight=FontWeight.SemiBold);Text(SimpleDateFormat("EEE, MMM d · HH:mm",Locale.getDefault()).format(Date(x.timestamp)),color=Muted,fontSize=11.sp,modifier=Modifier.padding(top=5.dp))};IconButton({edit=x}){Icon(Icons.Outlined.Edit,null,tint=Muted)};IconButton({s.deleteIdea(x);rev++}){Icon(Icons.Outlined.DeleteOutline,null,tint=Muted)}};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){IdeaState.entries.forEach{state->FilterChip(selected=x.state==state,onClick={s.p.edit().putString("ideas",IdeaCodec.setState(s.p.getString("ideas","")?:"",x.timestamp,state)).apply();rev++},label={Text(state.name)})}}}}};edit?.let{x->var t by remember(x){mutableStateOf(x.text)};AlertDialog({edit=null},{Button({s.updateIdea(x,t);edit=null;rev++}){Text("Save")}},dismissButton={TextButton({edit=null}){Text("Cancel")}},text={OutlinedTextField(t,{t=it},shape=RoundedCornerShape(16.dp))},title={Text("Edit idea")})}}
